use /lib
use /ui
from /ui/components/selection-popover import SelectionPopoverScope
from /scope/lsp import LSP
from /ui/components/file-tree import FileTreeScope
from /scope/open-file import OpenFileScope

export ui-component EditorScope:
    concept: {EditorConcept}

concept EditorConcept:
    pitch:
        An editor for a file opened from the @{FileTreeScope}, or anywhere else
        the @{OpenFileScope} says, with language support for Piton files.

    shape: {EditorShape}

shape EditorShape:
    description:
        Editable and syntax highlighted, under a header with the file's path in
        the project, a dot while it has unsaved changes, a save button, and a
        close button.

    syntaxHighlighting:
        Every file is highlighted in its language, using the grammars gpui-kit's
        editor comes with: Piton, and Astro, Bash, C, C++, C#, CMake, CSS,
        diffs, EJS, Elixir, ERB, Go, GraphQL, HTML, Java, JavaScript, JSON,
        Kotlin, Lua, Make, Markdown, PHP, Protocol Buffers, Python, Ruby, Rust,
        Scala, Svelte, Swift, TOML, TSX, TypeScript, YAML, and Zig. SQL is left
        out, as its grammar can't be built alongside gpui.

        The language comes from the file's extension, ignoring case, including
        the other extensions a language goes by, such as .h for C, .hpp and .cc
        for C++, .jsx, .mjs, and .cjs for JavaScript, .mts and .cts for
        TypeScript, .htm for HTML, .exs for Elixir, .zsh for Bash, .yml for
        YAML, and .scss, .sass, and .less for CSS. Some files are known by their
        whole name instead: Makefile for Make, CMakeLists.txt for CMake,
        Cargo.lock for TOML, Gemfile and Rakefile for Ruby, and shell startup
        files like .bashrc and .zshrc for Bash. A file in any other language, or
        with no extension, is plain text.

    selectingText:
        Selecting text in the editor by dragging across it shows a
        @{SelectionPopoverScope} with four buttons:
        - Cut, with a scissors icon, which puts the selected text on the clipboard and removes it from the file
        - Copy, with a copy icon, which puts the selected text on the clipboard
        - Paste, with a clipboard icon, which puts what is on the clipboard in place of the selected text
        - Send to Prompt, with a paperclip icon, which attaches the selected text to the prompt, as attaching text selected in an answer does

        Cut, Copy, and Paste do just what their shortcuts do in the editor, and
        can be undone the same way. Cut and Paste are disabled while the file
        can't be edited yet. After any of them the editor keeps focus. The
        popover also closes when the text changes, or when the file closes.

    saving:
        Ctrl+S (Cmd+S on macOS) or the save button writes the file to disk. A
        file that cannot be saved keeps its changes and says why beneath the
        header.

    languageSupport:
        overview:
            A Piton file (`.pi`) is edited with the project's @{LSP} server,
            shared with the chat input, which sees the editor's unsaved text:
            the file is opened with `textDocument/didOpen`, kept current with
            full-text `textDocument/didChange`, reported with
            `textDocument/didSave` when saved, and closed with
            `textDocument/didClose` when the editor closes or shows another
            file. Other files are edited without language support, as is a Piton
            file while the server is not running.

        completions:
            `textDocument/completion` is requested after typing a letter, a
            digit, an opening curly brace, a period, a dollar sign, an at sign,
            a colon, or an underscore, and narrowed and ordered as in the chat
            input. Accepting a completion also applies the import the server
            attaches to it.

        hover:
            Hovering a name shows the server's `textDocument/hover`.

        definitions:
            Ctrl-clicking (Cmd-clicking on macOS) a name goes to its
            `textDocument/definition`. A definition in another file opens that
            file at the definition, as the @{OpenFileScope} says.

        diagnostics:
            What the server publishes for the file is underlined, with the
            message shown on hover, and kept while the text is edited until the
            server publishes again.

        quickFixes:
            Ctrl+. (Cmd+. on macOS) lists the server's `textDocument/codeAction`
            fixes at the cursor, and picking one applies its edits to the file.

    replacing:
        Opening another file shows that file in its place. While there are
        unsaved changes, it first asks whether to discard them.

    closing:
        A close button above the file closes it. While there are unsaved
        changes, it first asks whether to discard them.
//! A file opened from the project tree, in an editor: syntax highlighted,
//! saved with Ctrl/Cmd+S, and for Piton files backed by the project's
//! `piton lsp` for completions, hover, definitions, diagnostics and quick
//! fixes. A header above it shows its path in the project, whether it has
//! unsaved changes, and save and close buttons.

use std::ops::Range;
use std::path::{Path, PathBuf};
use std::rc::Rc;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use gpui_kit::assets::IconName;
use gpui_kit::component::button::{Button, ButtonVariant, ButtonVariants as _};
use gpui_kit::component::dialog::DialogButtonProps;
use gpui_kit::component::input::{
    CodeActionProvider, CompletionProvider, Copy, Cut, DefinitionProvider, Editor, EditorState,
    Enter, HoverProvider, InputEvent, Paste, Rope, ShowDocumentHandler,
};
use gpui_kit::component::{
    ActiveTheme as _, Disableable as _, Sizable as _, StyledExt as _, WindowExt as _, h_flex,
    v_flex,
};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;
use lsp_types::{
    CodeAction, CodeActionOrCommand, CompletionContext, CompletionResponse, CompletionTextEdit,
    DocumentChanges, GotoDefinitionResponse, Hover, Location, LocationLink, OneOf, Position,
    TextEdit, WorkspaceEdit,
};
use serde_json::{Value, json};

use crate::piton_lsp::{self, LspClient};
use crate::piton_syntax;
use crate::project_directory::ProjectDirectory;
use crate::project_lsp::ProjectLsp;
use crate::selection_popover::{SelectionAction, selection_popover};

actions!(file_view, [SaveFile]);

const CONTEXT: &str = "FileView";

/// How often what the server published is collected.
const DIAGNOSTICS_INTERVAL: Duration = Duration::from_millis(100);

#[cfg(target_os = "macos")]
const SAVE_SHORTCUT: &str = "⌘S";
#[cfg(not(target_os = "macos"))]
const SAVE_SHORTCUT: &str = "Ctrl+S";

pub fn bind_keys(cx: &mut App) {
    cx.bind_keys([
        #[cfg(target_os = "macos")]
        KeyBinding::new("cmd-s", SaveFile, Some(CONTEXT)),
        #[cfg(not(target_os = "macos"))]
        KeyBinding::new("ctrl-s", SaveFile, Some(CONTEXT)),
    ]);
}

/// Emitted when the file is to be closed.
pub struct CloseFile;

/// Emitted to attach text selected in the editor to the prompt.
pub struct SendToPrompt(pub String);

/// Emitted to open the file holding a definition, at the definition.
pub struct OpenDefinition {
    pub path: PathBuf,
    pub position: Position,
}

/// The editor is never narrower than this many columns of text.
pub const MIN_COLUMNS: usize = 80;

/// Columns beside the line numbers' digits: their margins, the fold icons,
/// and the editor's padding and scrollbar.
const GUTTER_EXTRA_COLUMNS: usize = 6;

pub struct FileView {
    path: PathBuf,
    /// The file's path within the project, or in full outside of one.
    title: SharedString,
    editor: Entity<EditorState>,
    /// Why the file could not be shown, once reading it failed.
    error: Option<SharedString>,
    /// Why the file could not be saved, until it next saves.
    save_error: Option<SharedString>,
    /// The text as last read from or written to disk; `None` until read.
    saved: Option<String>,
    dirty: bool,
    /// The file as open in `piton lsp`, while it is a Piton file and the
    /// server is running.
    document: Option<Arc<Document>>,
    /// What the server last published for the file.
    diagnostics: Vec<lsp_types::Diagnostic>,
    /// Where the popover for selected text shows, while it does: where the
    /// drag that selected the text ended.
    selection_popover: Option<Point<Pixels>>,
    _load: Task<()>,
    _save: Task<()>,
    _watch_diagnostics: Task<()>,
    _subscriptions: Vec<Subscription>,
}

impl EventEmitter<CloseFile> for FileView {}
impl EventEmitter<SendToPrompt> for FileView {}
impl EventEmitter<OpenDefinition> for FileView {}

impl FileView {
    /// Opens the file at `path`, with the cursor at `position` if given.
    pub fn new(
        path: PathBuf,
        position: Option<Position>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Self {
        let title = match ProjectDirectory::get(cx) {
            Some(root) => path
                .strip_prefix(&root)
                .unwrap_or(&path)
                .display()
                .to_string(),
            None => path.display().to_string(),
        };
        let language = language_for(&path);
        let editor = cx.new(|cx| {
            EditorState::new(window, cx)
                .language(language)
                .soft_wrap(false)
                .placeholder("Loading…")
        });

        let subscriptions = vec![
            cx.subscribe_in(
                &editor,
                window,
                |this, _, event: &InputEvent, window, cx| {
                    if matches!(event, InputEvent::Change) {
                        // What was selected has changed under the popover.
                        this.selection_popover = None;
                        this.on_edit(window, cx);
                    }
                },
            ),
            cx.observe_global_in::<ProjectLsp>(window, |this, _, cx| this.attach_lsp(cx)),
        ];

        let read = cx.background_spawn({
            let path = path.clone();
            async move { std::fs::read_to_string(path) }
        });
        let load = cx.spawn_in(window, async move |this, cx| {
            let text = read.await;
            this.update_in(cx, |this, window, cx| {
                match text {
                    Ok(text) => {
                        this.editor.update(cx, |editor, cx| {
                            editor.set_value(text, window, cx);
                            if let Some(position) = position {
                                editor.set_cursor_position(position, window, cx);
                            }
                        });
                        // As the editor holds it, line endings normalized.
                        this.saved = Some(this.editor.read(cx).value().to_string());
                        this.attach_lsp(cx);
                    }
                    Err(err) => {
                        this.error = Some(format!("Could not show this file: {err}").into())
                    }
                }
                cx.notify();
            })
            .ok();
        });

        Self {
            path,
            title: title.into(),
            editor,
            error: None,
            save_error: None,
            saved: None,
            dirty: false,
            document: None,
            diagnostics: Vec::new(),
            selection_popover: None,
            _load: load,
            _save: Task::ready(()),
            _watch_diagnostics: Task::ready(()),
            _subscriptions: subscriptions,
        }
    }

    /// The file shown.
    pub fn path(&self) -> &std::path::Path {
        &self.path
    }

    pub fn title(&self) -> SharedString {
        self.title.clone()

