    #[test]
    fn files_are_highlighted_in_their_language() {
        use gpui_kit::component::highlighter::LanguageRegistry;

        let cases = [
            ("src/main.rs", "rust"),
            ("app.py", "python"),
            ("index.ts", "typescript"),
            ("view.tsx", "tsx"),
            ("util.mjs", "javascript"),
            ("button.jsx", "javascript"),
            ("main.go", "go"),
            ("lib.h", "c"),
