            ("Program.cs", "csharp"),
            ("style.scss", "css"),
            ("page.html", "html"),
            ("README.md", "markdown"),
            ("Cargo.toml", "toml"),
            ("Cargo.lock", "toml"),
            ("config.yml", "yaml"),
            ("data.json", "json"),
            ("run.sh", "bash"),
            (".zshrc", "bash"),
            ("Makefile", "make"),
            ("CMakeLists.txt", "cmake"),
            ("app.rb", "ruby"),
