        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("project-directory", cx);
        })
        .unwrap();
        cx.run_until_parked();
        let picker = main.read_with(cx, |main, _| {
            main.project_picker.clone().expect("no picker")
        });
        assert_eq!(
            cx.update(|cx| cx.windows().len()),
