        )
        .unwrap();
        std::fs::write(dir.join("spec/index.pi"), "").unwrap();
        let dir = std::fs::canonicalize(&dir).unwrap();

        cx.update(|cx| {
            gpui_kit::init(cx);
            piton_syntax::init();
